public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
   // Initialize a hash set to store the visited n-tersections
   Set&lt;Integer&gt; visited = new HashSet&lt;&gt;();

   // Add the starting n-tersection to the visited set
   visited.add(start[0] * n + start[1]);

   // Create a queue to store the n-tersections to visit
   Queue&lt;Integer[]&gt; queue = new LinkedList&lt;&gt;();

   // Add the starting n-tersection to the queue
   queue.add(start);

   // Loop until the queue is empty
   while (!queue.isEmpty()) {
       // Get the current n-tersection from the front of the queue
       Integer[] current = queue.remove();

       // If the current n-tersection is the ending n-tersection, return "can be travelled"
       if (current[0] * n + current[1] == end[0] * n + end[1]) {
           return "can be travelled";
       }

       // Loop through the paths
       for (int[] path : paths) {
           // If the current n-tersection is connected to the next n-tersection by a path, add the next n-tersection to the queue
           if (isConnected(current, path)) {
               queue.add(new Integer[] {path[0], path[1]});
           }
       }
   }

   // If the queue is empty and the current n-tersection is not the ending n-tersection, return "cannot be travelled"
   return "cannot be travelled";
}

private static boolean isConnected(Integer[] current, int[] path) {
    // Check if the current n-tersection's row is equal to the next n-tersection's row
    if (current[0] != path[0]) {
        return false;
    }

    // Check if the current n-tersection's column is one less than the next n-tersection's column
    if (current[1] != path[1] - 1) {
        return false;
    }

    return true;
}

