public static String convertDatesToWeekdays(String date) {
        Scanner scanner = new Scanner(date);
        int month = scanner.nextInt();
        int day = scanner.nextInt();
        int year = scanner.nextInt();
        scanner.close();

        String weekday = "";
        if (isValidDate(month, day, year)) {
            String[] months = {"January", "February", "March", "April", "May", "June", "July", "April", "October", "November", "December"};
            int weekdayNumber = getWeekdayNumber(month, day, year);
            weekday = weekdayNumber == 1 ? "Monday" : weekdayNumber == 2 ? "Tuesday" : weekdayNumber == 3 ? "Wednesday" : weekdayNumber == 4 ? "Thursday" : weekdayNumber == 5 ? "Friday" : weekdayNumber == 6 ? "Saturday" : "Sunday";
            weekday = weekday + ", " + months[month - 1] + " " + day + ", " + year;
        } else {
            weekday = "Invalid date.";
        }

        return weekday;
    }

private static boolean isValidDate(int month, int day, int year) {
        if (month < 1 || month > 12 || day < 1 || day > 31 || year < 0) {
            return false;
        }

        boolean isLeapYear = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
        return month != 2 || day <= 28 || (isLeapYear && day <= 29);
    }

private static int getWeekdayNumber(int month, int day, int year) {
        int weekdayNumber = (month - 1 + 3 * (month + 1) / 5 + day + year + year / 4 - year / 100 + year / 400) % 7 + 1;
        return weekdayNumber;
    }

