public int minTime(int n, int[][] edges, boolean[] hasApple) {
  int[] time = new int[n];
  boolean[] visited = new boolean[n];

  for (int i = 0; i < n; i++) {
    if (!visited[i] && hasApple[i]) {
      dfs(i, time, visited, edges, hasApple);
    }
  }

  int min = 0;
  for (int i = 0; i < n; i++) {
    if (hasApple[i]) {
      min = Math.max(min, time[i]);
    }
  }

  return min;
}

private void dfs(int curr, int[] time, boolean[] visited, int[][] edges, boolean[] hasApple) {
  visited[curr] = true;
  int children = 0;
  for (int i = 0; i < edges[curr].length; i++) {
    int child = edges[curr][i];
    if (!visited[child] && hasApple[child]) {
      dfs(child, time, visited, edges, hasApple);
      children++;
    }
  }

  if (children > 0) {
    time[curr] = time[curr] + children + 1;
  }
}

