  int aY = points[0][1];
  int bX = points[1][0];
  int bY = points[1][1];
  int cX = points[2][0];
  int cY = points[2][1];

  int crossProduct = (bX - aX) * (cY - aY) - (bY - aY) * (cX - aX);
